```rust
use core::cmp::Ordering;
use std::collections::BinaryHeap;

const MAGIC_MISSILE_MANA_COST: u32 = 53;
const MAGIC_MISSILE_DAMAGE: u32 = 4;

const DRAIN_MANA_COST: u32 = 73;
const DRAIN_AMOUNT: u32 = 2;

const SHIELD_MANA_COST: u32 = 113;
const SHIELD_DURATION: u32 = 6;
const SHIELD_BONUS_ARMOR: u32 = 7;

const POISON_MANA_COST: u32 = 173;
const POISON_DURATION: u32 = 6;
const POISON_DAMAGE: u32 = 3;

const RECHARGE_MANA_COST: u32 = 229;
const RECHARGE_DURATION: u32 = 5;
const RECHARGE_AMOUNT: u32 = 101;

#[derive(Debug, PartialEq, Clone)]
enum EffectType {
    Shield,
    Poison,
    Recharge,
}

#[derive(Debug, Clone)]
struct Effect {
    r#type: EffectType,
    timer: u32,
}

#[derive(Debug, Default, Clone)]
struct Character {
    hp: u32,
    mana: u32,
    damage: u32,
    armor: u32,
    bonus_armor: u32,
    effects: Vec<Effect>,
}

impl Character {
    fn apply_effects(&mut self) {
        self.bonus_armor = 0;

        let mut i = 0;
        while i < self.effects.len() {
            if self.effects[i].timer <= 0 {
                self.effects.swap_remove(i);
                continue;
            }

            match self.effects[i].r#type {
                EffectType::Shield => {
                    self.apply_shield();
                }

                EffectType::Poison => {
                    self.apply_poison();
                }
                EffectType::Recharge => {
                    self.apply_mana_recharge();
                }
            }

            self.effects[i].timer = self.effects[i].timer.saturating_sub(1);
            i += 1;
        }
    }

    fn apply_shield(&mut self) {
        self.bonus_armor = self.bonus_armor.saturating_add(SHIELD_BONUS_ARMOR);
    }

    fn apply_poison(&mut self) {
        self.hp = self.hp.saturating_sub(POISON_DAMAGE);
    }

    fn apply_mana_recharge(&mut self) {
        self.mana = self.mana.saturating_add(RECHARGE_AMOUNT);
    }

    fn cast_magic_missile(&mut self, other: &mut Character) -> bool {
        if self.mana >= MAGIC_MISSILE_MANA_COST {
            self.mana -= MAGIC_MISSILE_MANA_COST;
            other.hp = other.hp.saturating_sub(MAGIC_MISSILE_DAMAGE);
            return true;
        }
        return false;
    }

    fn cast_drain(&mut self, other: &mut Character) -> bool {
        if self.mana >= DRAIN_MANA_COST {
            self.mana -= DRAIN_MANA_COST;
            other.hp = other.hp.saturating_sub(DRAIN_AMOUNT);
            self.hp = self.hp.saturating_add(DRAIN_AMOUNT);
            return true;
        }
        return false;
    }

    fn has_effect(&self, effect_type: EffectType) -> bool {
        for effect in self.effects.iter() {
            if effect.r#type == effect_type {
                return true;
            }
        }
        return false;
    }

    fn cast_shield(&mut self) -> bool {
        if self.mana >= SHIELD_MANA_COST {
            if !self.has_effect(EffectType::Shield) {
                self.mana -= SHIELD_MANA_COST;
                self.effects.push(Effect {
                    r#type: EffectType::Shield,
                    timer: SHIELD_DURATION,
                });
                return true;
            }
        }
        return false;
    }

    fn cast_poison(&mut self, other: &mut Character) -> bool {
        if self.mana >= POISON_MANA_COST {
            if !other.has_effect(EffectType::Poison) {
                self.mana -= POISON_MANA_COST;
                other.effects.push(Effect {
                    r#type: EffectType::Poison,
                    timer: POISON_DURATION,
                });
                return true;
            }
        }
        return false;
    }

    fn cast_recharge(&mut self) -> bool {
        if self.mana >= RECHARGE_MANA_COST {
            if !self.has_effect(EffectType::Recharge) {
                self.mana -= RECHARGE_MANA_COST;
                self.effects.push(Effect {
                    r#type: EffectType::Recharge,
                    timer: RECHARGE_DURATION,
                });
                return true;
            }
        }
        return false;
    }

    fn attack(&self, other: &mut Character) {
        let total_armor = other.armor + other.bonus_armor;
        let total_damage = std::cmp::max(1, self.damage.saturating_sub(total_armor));
        other.hp = other.hp.saturating_sub(total_damage);
    }
}

#[derive(Debug, Clone)]
enum Spell {
    MagicMissile,
    Drain,
    Shield,
    Poison,
    Recharge,
}

const SPELLS: [Spell; 5] = [
    Spell::MagicMissile,
    Spell::Drain,
    Spell::Shield,
    Spell::Poison,
    Spell::Recharge,
];

#[derive(Debug, Clone, Default)]
enum GameStatus {
    #[default]
    Ongoing,
    PlayerWon(bool),
}

#[derive(Debug, Default)]
struct GameState {
    player: Character,
    opp: Character,
    status: GameStatus,
    spell_sequence: Vec<Spell>,
    mana_spent: u32,
}

impl PartialEq for GameState {
    fn eq(&self, other: &Self) -> bool {
        self.mana_spent == other.mana_spent
    }
}

impl Eq for GameState {}

impl Ord for GameState {
    fn cmp(&self, other: &Self) -> Ordering {
        other.mana_spent.cmp(&self.mana_spent) // Reversed
    }
}

impl PartialOrd for GameState {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn next_states(state: &GameState) -> Vec<GameState> {
    let mut player = state.player.clone();
    let mut opp = state.opp.clone();

    player.apply_effects();
    opp.apply_effects();

    if opp.hp < 1 {
        return vec![GameState {
            player: player,
            opp: opp,
            status: GameStatus::PlayerWon(true),
            mana_spent: state.mana_spent,
            spell_sequence: state.spell_sequence.clone(),
        }];
    }

    let mut all_results = vec![];
    for spell in SPELLS.iter() {
        let mut player = player.clone();
        let mut opp = opp.clone();
        let cast_successful = match spell {
            Spell::MagicMissile => player.cast_magic_missile(&mut opp),
            Spell::Drain => player.cast_drain(&mut opp),
            Spell::Shield => player.cast_shield(),
            Spell::Poison => player.cast_poison(&mut opp),
            Spell::Recharge => player.cast_recharge(),
        };
        if cast_successful {
            let mut spell_sequence = state.spell_sequence.clone();
            spell_sequence.push(spell.clone());
            let mana_cost = match spell {
                Spell::MagicMissile => MAGIC_MISSILE_MANA_COST,
                Spell::Drain => DRAIN_MANA_COST,
                Spell::Shield => SHIELD_MANA_COST,
                Spell::Poison => POISON_MANA_COST,
                Spell::Recharge => RECHARGE_MANA_COST,
            };
            let mana_spent = state.mana_spent.saturating_add(mana_cost);

            player.apply_effects();
            opp.apply_effects();

            if opp.hp < 1 {
                all_results.push(GameState {
                    player: player,
                    opp: opp,
                    status: GameStatus::PlayerWon(true),
                    mana_spent: mana_spent,
                    spell_sequence: spell_sequence,
                });
                continue;
            }

            opp.attack(&mut player);

            if player.hp < 1 {
                all_results.push(GameState {
                    player: player,
                    opp: opp,
                    status: GameStatus::PlayerWon(false),
                    mana_spent: mana_spent,
                    spell_sequence: spell_sequence.clone(),
                });
                continue;
            }

            all_results.push(GameState {
                player: player,
                opp: opp,
                status: GameStatus::Ongoing,
                spell_sequence: spell_sequence,
                mana_spent: mana_spent,
            });
        }
    }

    all_results
}

fn get_terminal_state(state: GameState) -> Option<GameState> {
    let mut queue = BinaryHeap::new();
    queue.push(state);

    while let Some(state) = queue.pop() {
        if let GameStatus::PlayerWon(won) = state.status {
            if won {
                return Some(state);
            }
            continue;
        }
        let states = next_states(&state);
        for state in states {
            queue.push(state);
        }
    }
    None
}

