export default {
  async fetch(request, env) {
    // 处理 CORS
    if (request.method === "OPTIONS") {
      return handleOptions(request);
    }

    if (request.method !== "POST") {
      return new Response("只允许 POST 请求", { status: 405 });
    }

    // 使用环境变量中的 API 密钥
    const apiKey = env.CLOUDFLARE_API_KEY;
    if (!apiKey) {
      return new Response("缺少 API 令牌", { status: 401 });
    }

    const accountId = env.CLOUDFLARE_ACCOUNT_ID;

    try {
      const body = await request.json();

      let model = body.model;
      if (!model.startsWith("@cf/")) {
        model = `@cf/${model}`;
      }

      const cfApiUrl = `https://api.cloudflare.com/client/v4/accounts/${accountId}/ai/run/${model}`;

      const aiResponse = await fetch(cfApiUrl, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${apiKey}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          messages: body.messages,
          max_tokens: body.max_tokens,
          temperature: body.temperature,
          // 可以根据需要添加其他参数
        }),
      }).then(res => res.json());

      if (!aiResponse.success) {
        throw new Error(aiResponse.errors[0].message);
      }

      // 直接返回纯文本响应
      const textResponse = aiResponse.result.response;

      return new Response(textResponse, {
        headers: {
          "Content-Type": "text/plain",
          "Access-Control-Allow-Origin": "*",
        },
      });
    } catch (error) {
      console.error('Error in worker:', error);
      return new Response('Internal Server Error: ' + error.message, { 
        status: 500,
        headers: { 'Content-Type': 'text/plain' }
      });
    }
  }
};

function handleOptions(request) {
  return new Response(null, {
    headers: {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, Authorization',
      'Access-Control-Max-Age': '86400',
    }
  });
}

